package com.bank.kernel;

// What APM / metrics / traces can see — the application and JVM only.
public class AppLayerView {
    private final long observedLatencyMs;     // what the caller's trace measured
    private final long downstreamSelfReportedMs; // what the downstream span reported
    private final double errorRate;
    private final double heapPercent;
    private final long gcPauseMs;

    public AppLayerView(long observedLatencyMs, long downstreamSelfReportedMs,
                        double errorRate, double heapPercent, long gcPauseMs) {
        this.observedLatencyMs = observedLatencyMs;
        this.downstreamSelfReportedMs = downstreamSelfReportedMs;
        this.errorRate = errorRate;
        this.heapPercent = heapPercent;
        this.gcPauseMs = gcPauseMs;
    }

    // The gap APM cannot explain: time lost BETWEEN services.
    public long unexplainedGapMs() { return observedLatencyMs - downstreamSelfReportedMs; }

    public boolean appLayerLooksClean() {
        return errorRate == 0.0 && heapPercent < 80 && gcPauseMs < 200;
    }
    public long getObservedLatencyMs() { return observedLatencyMs; }
}
