package com.bank.kernel;

// What eBPF can see BELOW the application — kernel/network/scheduler/disk.
public class KernelLayerProbe {
    private final int tcpRetransmitsPer5s;
    private final long runQueueLatencyMs;     // scheduler delay (CPU starvation)
    private final long diskIoWaitMs;
    private final long majorPageFaultsPer5s;

    public KernelLayerProbe(int tcpRetransmitsPer5s, long runQueueLatencyMs,
                            long diskIoWaitMs, long majorPageFaultsPer5s) {
        this.tcpRetransmitsPer5s = tcpRetransmitsPer5s;
        this.runQueueLatencyMs = runQueueLatencyMs;
        this.diskIoWaitMs = diskIoWaitMs;
        this.majorPageFaultsPer5s = majorPageFaultsPer5s;
    }
    public int getTcpRetransmitsPer5s() { return tcpRetransmitsPer5s; }
    public long getRunQueueLatencyMs() { return runQueueLatencyMs; }
    public long getDiskIoWaitMs() { return diskIoWaitMs; }
    public long getMajorPageFaultsPer5s() { return majorPageFaultsPer5s; }
}
