package com.bank.kernel;

import java.util.logging.Logger;

// If the app layer is clean but latency is high, drop to the kernel probe (eBPF).
public class RootCauseAnalyzer {
    private static final Logger log = Logger.getLogger(RootCauseAnalyzer.class.getName());

    public void analyze(AppLayerView app, KernelLayerProbe kernel) {
        log.info(() -> "APM view: observed latency " + app.getObservedLatencyMs()
                + "ms, unexplained gap " + app.unexplainedGapMs() + "ms");

        if (app.appLayerLooksClean() && app.unexplainedGapMs() > 100) {
            log.warning("APM shows NO application-level cause but latency is high "
                      + "-> dropping to eBPF kernel probes (below the app)");

            if (kernel.getTcpRetransmitsPer5s() > 50)
                log.severe(() -> "eBPF: " + kernel.getTcpRetransmitsPer5s()
                        + " TCP retransmits/5s — packet drops re-sending, silent latency");
            if (kernel.getRunQueueLatencyMs() > 20)
                log.severe(() -> "eBPF: run-queue latency " + kernel.getRunQueueLatencyMs()
                        + "ms — CPU-starved by a noisy neighbour, request waited for CPU");
            if (kernel.getDiskIoWaitMs() > 50)
                log.warning(() -> "eBPF: disk I/O wait " + kernel.getDiskIoWaitMs()
                        + "ms — storage blocking");
            if (kernel.getMajorPageFaultsPer5s() > 1000)
                log.warning(() -> "eBPF: " + kernel.getMajorPageFaultsPer5s()
                        + " major page faults/5s — memory pressure");

            log.info("Root cause found BELOW the application — invisible to APM alone.");
        } else if (!app.appLayerLooksClean()) {
            log.info("Application layer has a visible cause — handle it with APM, no eBPF needed.");
        } else {
            log.info("Latency within normal range — no action.");
        }
    }
}
