package com.bank.kernel;

import java.util.logging.*;

// Runnable demo: APM is clean yet latency is high; eBPF finds the kernel cause.
public class EbpfDemo {
    private static final Logger log = Logger.getLogger(EbpfDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — transfer latency spike with clean APM");

        // APM: caller saw 800ms, account-svc self-reported 20ms -> 780ms gap.
        // Heap healthy, no GC, zero errors — application layer looks perfect.
        AppLayerView app = new AppLayerView(800, 20, 0.0, 61.0, 40);

        // eBPF kernel probes between the transfer pod and the account pod.
        KernelLayerProbe kernel = new KernelLayerProbe(
            180,   // TCP retransmits per 5s — packet drops
            35,    // run-queue latency ms — CPU starvation
            8,     // disk I/O wait ms — fine
            120);  // page faults — fine

        new RootCauseAnalyzer().analyze(app, kernel);

        log.info("Fix: move noisy-neighbour pod off this node, investigate flaky NIC/overlay; "
               + "transfer SAV2001->CUR3001 latency returns to normal.");
    }
}
